    try { fs.closeSync(errFd); } catch (_) {}
    return { ok: false, error: 'spawn 失败: ' + String((e && e.message) || e), argv: argv };
  }
  child.unref();

  try { fs.closeSync(outFd); } catch (_) {}
  try { fs.closeSync(errFd); } catch (_) {}
  return { ok: true, pid: child.pid, argv: argv, out_log: outLog, err_log: errLog };
