  const found = [];
  for (const re of [OV_STATIC_IMPORT_RE, OV_DYNAMIC_IMPORT_RE, OV_SIDE_EFFECT_IMPORT_RE]) {
    re.lastIndex = 0;
    let m; while ((m = re.exec(source))) found.push(m[1]);
  }
  return found;
