  'detected-running': '已在运行，未做改动',
  'detected-not-running': '未运行（本次未要求启动）',
  'kill-error': 'kill 失败，未重启',
  'port-still-busy': '端口仍被占用，未重启',
  'skipped-self-in-dsh-gui': '检测到从 DSH GUI 内调用，已跳过重启',
  'restart-no-pid': '端口有响应但找不到进程 pid，已跳过',
};

function dshWebLine(w) {
  if (!w || w.skipped) return '';
  let s = 'DSH web (' + (w.url || 'http://127.0.0.1:3080') + '): ';
  s += DSH_WEB_LABEL[w.action] || w.action || '';
  if (w.owner_pid) s += ' · 旧 pid ' + w.owner_pid;
  if (w.pid) s += ' · 新 pid ' + w.pid;
  if (w.bound === false) s += ' · 端口未确认 bind';
  return s;
}

const STATUS_META = {
  ok: { icon: '✓', label: '已最新', cls: 'foxup-ok' },
  upgradable: { icon: '↑', label: '可升级', cls: 'foxup-warn' },
  installable: { icon: '+', label: '未安装', cls: 'foxup-warn' },
  upgraded: { icon: '↑', label: '已升级', cls: 'foxup-done' },
  installed: { icon: '+', label: '已安装', cls: 'foxup-done' },
  external: { icon: '○', label: '外部渠道', cls: 'foxup-dim' },
  unknown: { icon: '?', label: '未知', cls: 'foxup-dim' },
  error: { icon: '✗', label: '失败', cls: 'foxup-err' },
};

function UpdateView(props) {
  const [busy, setBusy] = React.useState(false);
  const [error, setError] = React.useState('');
  const [data, setData] = React.useState(null);

  async function call(checkOnly) {
    setBusy(true);
    setError('');
    try {
      const res = await host.call('foxai_cli_update', { check_only: checkOnly });
      if (res && res.success) {
        setData(res);
      } else {
        setError((res && (res.error || res.stderr_tail)) || '调用失败');
        if (res && res.results) setData(res);
      }
    } catch (e) {
      setError(String((e && e.message) ? e.message : e));
    } finally {
      setBusy(false);
    }
  }

  function renderTable() {
    const rows = (data && data.results) || [];
    return React.createElement('table', { className: 'foxup-table' },
      React.createElement('thead', null,
        React.createElement('tr', null,
          React.createElement('th', null, '工具'),
          React.createElement('th', null, '状态'),
          React.createElement('th', null, '当前'),
          React.createElement('th', null, '最新'),
          React.createElement('th', null, '操作')
        )
      ),
      React.createElement('tbody', null,
        rows.length === 0
          ? React.createElement('tr', null, React.createElement('td', { colSpan: 5, className: 'foxup-dim' }, busy ? '执行中…（npm 操作可能需要几十秒）' : '尚无结果，点击上方按钮开始'))
          : rows.map(function (r, i) {
              const meta = STATUS_META[r.status] || { icon: '·', label: r.status, cls: 'foxup-dim' };
              return React.createElement('tr', { key: i },
                React.createElement('td', null, r.name + ' (' + r.id + ')'),
                React.createElement('td', { className: meta.cls }, meta.icon + ' ' + (meta.label === r.status ? r.status : r.status)),
                React.createElement('td', null, r.installed || '-'),
                React.createElement('td', null, r.latest || '-'),
                React.createElement('td', { className: r.error ? 'foxup-err' : '' }, r.error ? r.error : r.action)
              );
            })
      )
    );
  }

  return React.createElement('div', { className: 'foxup-card' },
    React.createElement('div', { className: 'foxup-header' },
      React.createElement('h3', null, 'AI CLI 工具更新'),
      React.createElement('div', { className: 'foxup-btns' },
        React.createElement('button', { className: 'foxup-btn', disabled: busy, onClick: function () { call(true); } }, busy ? '…' : '检查更新'),
        React.createElement('button', { className: 'foxup-btn foxup-btn-primary', disabled: busy, onClick: function () { call(false); } }, busy ? '执行中…' : '立即更新')
      )
    ),
    data && data.checked_at
      ? React.createElement('div', { className: 'foxup-meta' },
          (data.check_only ? '仅检查 · ' : '已执行更新 · ') + new Date(data.checked_at).toLocaleString() +
          (data.summary ? ' · 汇总 ' + JSON.stringify(data.summary) : '')
        )
      : null,
    renderTable(),
    data && data.dsh_web && !data.dsh_web.skipped
      ? React.createElement('div', { className: 'foxup-meta' }, dshWebLine(data.dsh_web))
      : null,
    data && data.output_tail
      ? React.createElement('details', { className: 'foxup-details' },
          React.createElement('summary', null, '执行输出'),
          React.createElement('pre', { className: 'foxup-pre' }, data.output_tail)
        )
      : null,
    error ? React.createElement('div', { className: 'foxup-error' }, error) : null
  );
}

const css = ''
  + '.foxup-card { font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif; color: var(--fg, #e6e6e6); padding: 12px; }\n'
  + '.foxup-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; padding-bottom: 8px; border-bottom: 1px solid var(--border, rgba(255,255,255,0.1)); }\n'
  + '.foxup-header h3 { margin: 0; font-size: 15px; font-weight: 600; }\n'
  + '.foxup-btns { display: flex; gap: 8px; }\n'
  + '.foxup-btn { background: var(--btn, rgba(255,255,255,0.08)); color: inherit; border: 1px solid var(--border, rgba(255,255,255,0.15)); border-radius: 4px; padding: 5px 12px; font-size: 12px; cursor: pointer; }\n'
  + '.foxup-btn:hover:not(:disabled) { background: var(--btn-hover, rgba(255,255,255,0.15)); }\n'
  + '.foxup-btn:disabled { opacity: 0.5; cursor: not-allowed; }\n'
  + '.foxup-btn-primary { background: var(--accent, #4f8cff); color: white; border-color: var(--accent, #4f8cff); }\n'
  + '.foxup-btn-primary:hover:not(:disabled) { filter: brightness(1.1); }\n'
  + '.foxup-meta { font-size: 11px; opacity: 0.7; margin-bottom: 8px; }\n'
  + '.foxup-table { width: 100%; border-collapse: collapse; font-size: 12px; }\n'
  + '.foxup-table th { text-align: left; font-weight: 600; opacity: 0.75; padding: 4px 8px 4px 0; border-bottom: 1px solid var(--border, rgba(255,255,255,0.1)); }\n'
  + '.foxup-table td { padding: 5px 8px 5px 0; border-bottom: 1px solid var(--border, rgba(255,255,255,0.05)); vertical-align: top; word-break: break-word; }\n'
  + '.foxup-ok { color: #4caf50; }\n'
  + '.foxup-warn { color: #ffb300; }\n'
  + '.foxup-done { color: #29b6f6; }\n'
  + '.foxup-err { color: #ff5252; }\n'
  + '.foxup-dim { opacity: 0.6; }\n'
  + '.foxup-details { margin-top: 8px; font-size: 12px; }\n'
  + '.foxup-details summary { cursor: pointer; opacity: 0.75; padding: 4px 0; }\n'
  + '.foxup-pre { background: rgba(0,0,0,0.3); border: 1px solid var(--border, rgba(255,255,255,0.08)); border-radius: 4px; padding: 10px; font-size: 11px; line-height: 1.5; white-space: pre-wrap; word-break: break-word; max-height: 40vh; overflow-y: auto; margin: 6px 0 0; font-family: ui-monospace, "SF Mono", Menlo, monospace; }\n'
  + '.foxup-error { color: #ff5252; padding: 8px; margin-top: 8px; background: rgba(255,82,82,0.1); border-radius: 4px; font-size: 11px; white-space: pre-wrap; }\n';

return {
  apply(applyCtx) {
    const slots = applyCtx.get('slots');
    if (!slots) return;

    const styleDisposer = styles.insert(css);
    slots.inject('tool.view.cordis', function () {
      const dispose = slots.register(
        { name: 'tool.view.cordis', key: 'self' },
        function (props) { return React.createElement(UpdateView, props); }
      );
      return function () {
        try { dispose && dispose(); } catch (e) {  }
        try { styleDisposer && styleDisposer(); } catch (e) {  }
      };
    });
  },
};
